let data=ORION_DB.load(),cart=[],category="Semua",editing=null,formMode="",activeUser=null,receiptSale=null,supabase=null,toastTimer,checkoutOpen=false,checkoutBusy=false;
const localMode=()=>!window.ORION_SUPABASE_URL||!window.ORION_SUPABASE_ANON_KEY;
