function toast(s){const t=$("#toast");t.textContent=s;t.classList.add("show");clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove("show"),2600)}
function persist(){ORION_DB.save(data);if(supabase&&!window.__orionPullingRemote&&data.settings?.syncEnabled!==false){pushRemote().catch(err=>{console.warn("Sinkronisasi otomatis gagal",err);toast("Data lokal tersimpan, sinkronisasi online gagal")})}}
function activeProducts(){return data.products.filter(p=>p.active!==false)}
function product(id){return data.products.find(p=>p.id===Number(id))}
function livePromo(p){const now=today();return data.promos.find(x=>x.productId===p.id&&x.active&&x.start<=now&&x.end>=now)}
function priceFor(p){const promo=livePromo(p);if(!promo)return p.price;return Math.max(0,Math.round(promo.type==="percent"?p.price*(1-promo.amount/100):p.price-promo.amount))}
function promoDiscount(p){return Math.max(0,p.price-priceFor(p))}
function deliveryAmount(){const enabled=$("#delivery-enabled")?.checked;return enabled?Math.max(0,Number($("#delivery-fee")?.value)||0):0}
function totals(){const result=cart.reduce((a,i)=>{const p=product(i.id);if(!p)return a;const full=p.price*i.qty,paid=priceFor(p)*i.qty;a.qty+=i.qty;a.subtotal+=full;a.total+=paid;a.discount+=full-paid;a.hpp+=(Number(p.hpp)||0)*i.qty;return a},{qty:0,subtotal:0,total:0,discount:0,hpp:0});result.deliveryFee=deliveryAmount();result.delivery=!!$("#delivery-enabled")?.checked;result.total+=result.deliveryFee;return result}
function transactionsForDay(){return data.sales.filter(s=>String(s.createdAt).slice(0,10)===today())}
function requireOpen(){if(data.outletClosed){toast("Outlet sedang ditutup. Buka kembali melalui Pengaturan.");return false}return true}
function closeMobileNav(){if(window.matchMedia("(max-width: 780px)").matches){$("#app").classList.remove("nav-open");$("#nav-edge-toggle")?.setAttribute("aria-expanded","false");$("#nav-scrim")?.setAttribute("aria-hidden","true")}}
function setMobileNav(open){const app=$("#app");app.classList.toggle("nav-open",!!open);$("#nav-edge-toggle")?.setAttribute("aria-expanded",String(!!open));$("#nav-scrim")?.setAttribute("aria-hidden",String(!open))}
function userRole(){return String(activeUser?.role||'employee').toLowerCase()}
function roleLabel(){return ({owner:'Owner',admin:'Owner',manager:'Manajer',employee:'Kasir',cashier:'Kasir'})[userRole()]||'Kasir'}
function roleCan(action){const role=userRole();if(['owner','admin'].includes(role))return true;if(role!=='manager')return false;const map={void:'managerVoid',discount:'managerDiscount',menu:'managerMenu',settings:'managerSettings',reports:'managerReports'};return data.settings?.permissions?.[map[action]]!==false}
function canOpenPage(page){if(['owner','admin'].includes(userRole()))return true;if(userRole()==='manager')return page==='pengaturan'?roleCan('settings'):page==='keuangan'?false:page==='laporan'?roleCan('reports'):true;return page==='kasir'||page==='absensi'||page==='laporan'}
function applyRoleUI(){const role=userRole();$$('#main-nav [data-page]').forEach(b=>{b.hidden=!canOpenPage(b.dataset.page)});const closeBtn=$('#close-outlet-btn');if(closeBtn)closeBtn.hidden=!['owner','admin','manager'].includes(role);$('#user-label').textContent=(activeUser?.name||activeUser?.email||'Akun')+' · '+roleLabel()}
function showPage(page){const backBtn=$("#back-to-cashier");if(backBtn)backBtn.hidden=page==="kasir";const categoryLabel=$("#active-category-label");if(categoryLabel)categoryLabel.hidden=page!=="kasir";if(!canOpenPage(page)){toast('Akun '+roleLabel()+' tidak memiliki akses ke halaman ini.');return}$$(".page").forEach(p=>p.classList.toggle("active",p.id==="page-"+page));$$(".nav-btn").forEach(b=>b.classList.toggle("active",b.dataset.page===page));closeMobileNav();if(page==="menu")renderMenu();if(page==="promo")renderPromos();if(page==="stok")renderStock();if(page==="laporan")renderReport();if(page==="keuangan")renderFinance();if(page==="absensi")renderAttendance();if(page==="riwayat")renderSales();if(page==="pengaturan")renderSettings()}
function renderStatus(){if(data.settings?.hoursEnabled){try{const tz=data.settings.timezone||"Asia/Jakarta",parts=new Intl.DateTimeFormat("en-GB",{timeZone:tz,hour:"2-digit",minute:"2-digit",hourCycle:"h23"}).formatToParts(new Date()),now=Number(parts.find(p=>p.type==="hour")?.value||0)*60+Number(parts.find(p=>p.type==="minute")?.value||0),[oh,om]=(data.settings.openingTime||"09:00").split(":").map(Number),[ch,cm]=(data.settings.closingTime||"22:00").split(":").map(Number),open=oh*60+om,close=ch*60+cm;data.outletClosed=open<=close?!(now>=open&&now<close):!(now>=open||now<close)}catch(e){console.warn("Jadwal outlet tidak dapat diterapkan",e)}}$("#outlet-name-side").textContent=data.settings.outlet||"OR!ON CORNDOG";$("#outlet-state").textContent=data.outletClosed?"Tutup":"Buka";$("#outlet-state").className="pill "+(data.outletClosed?"closed":"open");$("#close-outlet-btn").textContent=data.outletClosed?"Buka Outlet":"Tutup Outlet";$("#connection-status").innerHTML=localMode()?"<i style='background:#d49b35'></i> Mode lokal":"<i></i> Backend online";$("#backend-status").textContent=localMode()?"Belum dikonfigurasi":"Supabase dikonfigurasi"}
function renderMetrics(){const list=transactionsForDay(),sales=list.reduce((a,s)=>a+s.total,0),hpp=list.reduce((a,s)=>a+s.hpp,0);$("#m-sales").textContent=money(sales);$("#m-hpp").textContent=money(hpp);$("#m-profit").textContent=money(sales-hpp);$("#m-count").textContent=list.length+" transaksi hari ini"}
function monthKey(d=new Date()){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`}
function salesByProduct(monthOnly=true){const counts={};(data.sales||[]).filter(s=>!monthOnly||(s.businessMonth|| (s.createdAt?monthKey(new Date(s.createdAt)):'') )===monthKey()).forEach(s=>(s.items||[]).forEach(i=>{const key=String(i.id);counts[key]=(counts[key]||0)+Number(i.qty||0)}));return counts}
function isSweetMozzarella(p){return String(p.category||'').toLowerCase()==='sweet mozzarella'}
function isSavoryMozzarella(p){return String(p.category||'').toLowerCase()==='savory mozzarella'}
function renderPosCategories(){const existing=[...new Set(activeProducts().map(p=>p.category))];const ordered=(data.categories||[]).filter(c=>existing.includes(c));const cats=['Semua',...ordered,...existing.filter(c=>!ordered.includes(c))];if(!cats.includes(category))category='Semua';if(!existing.length)category='Semua';$('#pos-categories').innerHTML=cats.map(c=>`<button class="chip ${category===c?'active':''}" data-pos-cat="${esc(c)}">${esc(c)}</button>`).join('')}
function renderPosProducts(){
 const q=$('#product-search').value.toLowerCase();
 const all=activeProducts().filter(p=>`${p.name} ${p.category}`.toLowerCase().includes(q));
 const filtered=all.filter(p=>category==='Semua'||p.category===category);
 const counts=salesByProduct();
 const qtyFor=id=>cart.find(i=>i.id===Number(id))?.qty||0;
 const compare=(a,b)=>(counts[String(b.id)]||0)-(counts[String(a.id)]||0)||String(a.name).localeCompare(String(b.name));
 const promos=filtered.filter(p=>!!livePromo(p)).sort(compare);
 const regular=filtered.filter(p=>!livePromo(p));
 const topSellers=all.filter(p=>(counts[String(p.id)]||0)>0).sort(compare).slice(0,8);
 const bestsellerIds=new Set(topSellers.map(p=>String(p.id)));
 const renderCard=p=>{const qty=qtyFor(p.id),disabled=false,bestseller=bestsellerIds.has(String(p.id));return `<article class="product-card ${disabled?'out-of-stock':''}"><div class="product-visual">${p.image?`<img src="${p.image}" alt="${esc(p.name)}" loading="lazy">`:''}</div><span class="product-category">${esc(p.category)}${bestseller?' <span class="best-seller" title="Sering dibeli / best seller" aria-label="Best seller">👍</span>':''}</span><span class="product-name">${esc(p.name)}</span><div class="product-bottom"><span class="product-price">${money(priceFor(p))}${livePromo(p)?` <s style="color:#aaa;font-size:9px">${money(p.price)}</s>`:''}</span><div class="product-qty" aria-label="Jumlah ${esc(p.name)}"><button type="button" data-card-qty="${p.id}" data-delta="-1" ${qty<=0?'disabled':''} aria-label="Kurangi ${esc(p.name)}">−</button><output>${qty}</output><button type="button" data-card-qty="${p.id}" data-delta="1" ${disabled?'disabled':''} aria-label="Tambah ${esc(p.name)}">+</button></div></div></article>`};
 const sections=[];
 if(promos.length)sections.push(`<section class="pos-category-section promo-products-section"><h3 class="pos-section-title"><span>Promo Aktif</span><small>${promos.length} menu</small></h3><div class="product-grid">${promos.map(renderCard).join('')}</div></section>`);
 if(topSellers.length)sections.push(`<section class="pos-category-section bestseller-section"><h3 class="pos-section-title"><span>👍 Best Seller</span><small>Terlaris</small></h3><div class="bestseller-strip">${topSellers.map(renderCard).join('')}</div></section>`);
 if(category==='Semua'){
   const groups=(data.categories||[]).filter(c=>regular.some(p=>p.category===c)).concat([...new Set(regular.map(p=>p.category))].filter(c=>!(data.categories||[]).includes(c)));
   for(const cat of groups){const items=regular.filter(p=>p.category===cat).sort(compare);sections.push(`<section class="pos-category-section"><h3 class="pos-section-title"><span>${esc(cat)}</span><small>${items.length} menu</small></h3><div class="product-grid">${items.map(renderCard).join('')}</div></section>`)}
 } else if(regular.length){regular.sort(compare);sections.push(`<section class="pos-category-section"><h3 class="pos-section-title"><span>${esc(category)}</span><small>${regular.length} menu</small></h3><div class="product-grid">${regular.map(renderCard).join('')}</div></section>`)}
 $('#pos-products').innerHTML=sections.join('')||'<div class="empty-state">Menu tidak ditemukan atau belum ditambahkan.</div>';
 const label=$('#active-category-label');if(label)label.textContent=(category==='Semua'?'Semua':category);
 if(window.__orionCategoryObserver)window.__orionCategoryObserver.disconnect();
 const updateActiveCategory=()=>{if(!label)return;const heads=[...document.querySelectorAll('#pos-products .pos-category-section:not(.promo-products-section):not(.bestseller-section) .pos-section-title')];if(!heads.length){label.textContent=(category==='Semua'?'Semua':category);return;}const topbar=document.querySelector('.topbar');const threshold=(topbar?.getBoundingClientRect().bottom||64)+Math.max(34,label.offsetHeight)+8;let active=heads[0];for(const h of heads){if(h.getBoundingClientRect().top<=threshold)active=h;else break;}const name=active.querySelector('span')?.textContent||category;label.textContent=name;};
 window.__orionCategoryObserver=()=>updateActiveCategory();
 if(!window.__orionCategoryScrollBound){window.addEventListener('scroll',updateActiveCategory,{passive:true});window.addEventListener('resize',updateActiveCategory,{passive:true});window.__orionCategoryScrollBound=true;}
 requestAnimationFrame(updateActiveCategory);

}
function renderCart(){const t=totals();const panel=$("#cart-panel");panel?.classList.toggle("cart-empty",cart.length===0);$("#sheet-cart-count").textContent=t.qty+" item";$("#sheet-cart-total").textContent=money(t.total);$("#cart-count").textContent=t.qty;$("#cart-subtotal").textContent=money(t.subtotal);$("#cart-discount").textContent="-"+money(t.discount);$("#cart-total").textContent=money(t.total);$("#cart-hpp").textContent=money(t.hpp);$("#cart-profit").textContent=money(t.total-t.hpp);$("#cart-items").innerHTML=cart.length?cart.map(i=>{const p=product(i.id);if(!p)return"";return `<div class="cart-item"><div><div class="cart-item-name">${esc(p.name)}</div><div class="cart-item-meta">${money(priceFor(p))} / pcs ${livePromo(p)?`· promo`:""}</div><div class="qty-control"><button type="button" data-qty="${p.id}" data-delta="-1" aria-label="Kurangi ${esc(p.name)}">−</button><span>${i.qty}</span><button type="button" data-qty="${p.id}" data-delta="1" aria-label="Tambah ${esc(p.name)}">+</button></div></div><div class="cart-item-total">${money(priceFor(p)*i.qty)}</div></div>`}).join(""):'<div class="empty">Belum ada pesanan.</div>';updatePayment();if(checkoutOpen)renderCheckout()}
function openCheckout(){if(!cart.length)return toast("Pilih menu terlebih dahulu.");checkoutOpen=true;$("#checkout-screen").classList.remove("hidden");document.body.classList.add("checkout-active");renderCheckout();updatePayment();}
function closeCheckout(){checkoutOpen=false;$("#checkout-screen").classList.add("hidden");document.body.classList.remove("checkout-active");}
function renderCheckout(){const t=totals();$("#checkout-items").innerHTML=cart.length?cart.map(i=>{const p=product(i.id);if(!p)return "";return `<article class="checkout-item"><div class="checkout-item-main"><strong>${esc(p.name)}</strong><span>${money(priceFor(p))} / item</span><div class="qty-control"><button type="button" data-qty="${p.id}" data-delta="-1" aria-label="Kurangi ${esc(p.name)}">−</button><span>${i.qty}</span><button type="button" data-qty="${p.id}" data-delta="1" aria-label="Tambah ${esc(p.name)}">+</button><button type="button" class="remove-item" data-remove-cart="${p.id}">Hapus</button></div></div><b>${money(priceFor(p)*i.qty)}</b></article>`}).join(""):'<div class="empty-state">Keranjang kosong. Kembali ke menu untuk memilih produk.</div>';
 $("#checkout-subtotal").textContent=money(t.subtotal);$("#checkout-discount").textContent="−"+money(t.discount);$("#checkout-total").textContent=money(t.total);$("#checkout-count").textContent=t.qty+" item";$("#checkout-hpp").textContent=money(t.hpp);$("#checkout-profit").textContent=money(t.total-t.hpp);updatePayment();}

function addCart(id){if(!requireOpen())return;const p=product(id);if(!p)return toast("Menu tidak ditemukan.");const i=cart.find(x=>x.id===Number(id));if(i)i.qty++;else cart.push({id:Number(id),qty:1});renderCart();renderPosProducts();toast(p.name+" ditambahkan")}
function changeQty(id,d){const i=cart.find(x=>x.id===Number(id)),p=product(id);if(!p)return;if(!i){if(d>0)return addCart(id);return}i.qty+=d;if(i.qty<=0)cart=cart.filter(x=>x.id!==Number(id));renderCart();renderPosProducts()}
function updatePayment(){const t=totals(),deliveryToggle=$("#delivery-enabled"),deliveryLabel=$("#delivery-fee-label"),deliveryRow=$("#checkout-delivery-row");if(deliveryLabel)deliveryLabel.classList.toggle("hidden",!deliveryToggle?.checked);if(deliveryRow)deliveryRow.classList.toggle("hidden",!deliveryToggle?.checked);if($("#checkout-delivery-fee"))$("#checkout-delivery-fee").textContent=money(t.deliveryFee);const cash=$("#payment-method").value==="Tunai",received=Number($("#cash-received").value)||0;$("#checkout-cash-label").classList.toggle("hidden",!cash);$("#checkout-cash-change").textContent=money(Math.max(0,received-t.total));$("#checkout-btn").disabled=!cart.length||!!data.outletClosed||checkoutBusy;$("#checkout-screen-btn").disabled=!cart.length||!requireCheckout(cash,received,t.total)||!!data.outletClosed||checkoutBusy;const panel=$("#cart-panel");if(panel){panel.classList.toggle("cart-has-items",cart.length>0);if(cart.length){$("#sheet-toggle-text").textContent="Buka pembayaran →"}else{panel.classList.remove("sheet-expanded");$("#cart-sheet-toggle")?.setAttribute("aria-expanded","false");$("#sheet-toggle-text").textContent="Pilih menu untuk mulai"}}}
function setCashPreset(value){const total=totals().total;const amount=value==="exact"?total:Number(value);$("#cash-received").value=String(amount);updatePayment();if(checkoutOpen)renderCheckout();}
function requireCheckout(cash,received,total){return !cash||received>=total}
function checkout(){if(checkoutBusy)return;if(!requireOpen()||!cart.length)return;const t=totals(),method=$("#payment-method").value,received=method==="Tunai"?(Number($("#cash-received").value)||0):t.total;if(method==="Tunai"&&received<t.total)return toast("Uang diterima belum mencukupi.");for(const i of cart){const p=product(i.id);if(!p)return toast("Menu tidak ditemukan.");}
 const summary=`Konfirmasi transaksi\n\n${t.qty} item${t.delivery?"\nOngkir delivery: "+money(t.deliveryFee):""}\nTotal: ${money(t.total)}\nMetode: ${method}${method==="Tunai"?"\nUang diterima: "+money(received)+"\nKembalian: "+money(received-t.total):""}\n\nSelesaikan pembayaran ini?`;if(!window.confirm(summary))return;
 checkoutBusy=true;updatePayment();let pendingSale=null;try{const sale=pendingSale={id:"OR-"+Date.now().toString().slice(-9),createdAt:new Date().toISOString(),businessMonth:monthKey(),payment:method,items:cart.map(i=>{const p=product(i.id);return{id:p.id,name:p.name,qty:i.qty,price:p.price,paidPrice:priceFor(p),discount:promoDiscount(p),hpp:Number(p.hpp)||0}}),subtotal:t.subtotal,discount:t.discount,delivery:!!t.delivery,deliveryFee:t.deliveryFee||0,total:t.total,hpp:t.hpp,profit:t.total-(t.deliveryFee||0)-t.hpp,received,change:method==="Tunai"?received-t.total:0,cashier:activeUser?.name||"Kasir",cashierEmail:activeUser?.email||"",shiftKey:currentShiftKey()};data.sales.unshift(sale);ORION_DB.save(data);if(supabase&&!window.__orionPullingRemote)pushRemote().catch(err=>{console.warn("Sinkronisasi otomatis gagal",err);toast("Transaksi tersimpan lokal; sinkronisasi online gagal")});cart=[];$("#cash-received").value="";if($("#delivery-enabled"))$("#delivery-enabled").checked=false;if($("#delivery-fee"))$("#delivery-fee").value="0";closeCheckout();renderAll();showReceipt(sale);if(data.settings?.hardware?.autoPrint){setTimeout(()=>{document.documentElement.style.setProperty("--receipt-width",Number(data.settings.hardware.paperSize||58)===80?"80mm":"58mm");window.print()},350)}if(data.settings?.hardware?.cashDrawer){toast("Transaksi tersimpan. Perintah laci uang memerlukan printer ESC/POS yang mendukung dan koneksi kompatibel.")}else toast("Transaksi tersimpan");}catch(err){if(pendingSale)data.sales=data.sales.filter(s=>s.id!==pendingSale.id);toast("Transaksi gagal disimpan. Stok tidak diubah.");console.error(err)}finally{checkoutBusy=false;updatePayment()}}
