async function compressMenuImage(file){const source=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(new Error("File tidak dapat dibaca"));r.readAsDataURL(file)});const img=await new Promise((resolve,reject)=>{const i=new Image();i.onload=()=>resolve(i);i.onerror=()=>reject(new Error("Format gambar tidak didukung"));i.src=source});const maxSide=640,scale=Math.min(1,maxSide/Math.max(img.naturalWidth||img.width,img.naturalHeight||img.height));const canvas=document.createElement("canvas");canvas.width=Math.max(1,Math.round((img.naturalWidth||img.width)*scale));canvas.height=Math.max(1,Math.round((img.naturalHeight||img.height)*scale));const ctx=canvas.getContext("2d",{alpha:false});if(!ctx)throw new Error("Canvas tidak tersedia");ctx.fillStyle="#ffffff";ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);let quality=.78,result=canvas.toDataURL("image/jpeg",quality);while(result.length>240000&&quality>.48){quality-=.08;result=canvas.toDataURL("image/jpeg",quality)}return result}
function openForm(title,fields,onSave,initial={}){formMode=title;$("#form-title").textContent=title;$("#form-fields").innerHTML=fields.map(f=>{const value=initial[f.name]??f.value??"";let input;if(f.type==="select")input=`<select name="${f.name}" ${f.required===false?"":"required"}>${(f.options||[]).map(o=>`<option value="${esc(o.value)}" ${String(o.value)===String(value)?"selected":""}>${esc(o.label)}</option>`).join("")}</select>`;else if(f.type==="textarea")input=`<textarea name="${f.name}" rows="3" ${f.required===false?"":"required"}>${esc(value)}</textarea>`;else if(f.type==="file")input=`<input name="${f.name}" type="file" accept="image/*" ${f.required===false?"":"required"}><small class="muted">Pilih foto dari HP. Gambar akan diperkecil agar penyimpanan lebih ringan.</small>${initial.image?`<img class="form-image-preview" src="${initial.image}" alt="Pratinjau gambar menu">`:""}`;else input=`<input name="${f.name}" type="${f.type||"text"}" value="${esc(value)}" ${f.min!==undefined?`min="${f.min}"`:""} ${f.step?`step="${f.step}"`:""} ${f.required===false?"":"required"} ${f.placeholder?`placeholder="${esc(f.placeholder)}"`:""}>`;return `<label class="${f.full?"full-field":""}">${esc(f.label)}${input}</label>`}).join("");$("#dynamic-form").onsubmit=e=>{e.preventDefault();const fd=new FormData(e.currentTarget),obj=Object.fromEntries(fd.entries());const file=fd.get("image");const finish=()=>{onSave(obj);$("#form-dialog").close()};if(file instanceof File&&file.size){if(!file.type.startsWith("image/"))return toast("File harus berupa gambar.");compressMenuImage(file).then(src=>{obj.image=src;finish()}).catch(err=>toast("Foto gagal diproses: "+err.message))}else finish()};$("#form-dialog").showModal()}
function productFields(p={}){return[{name:"name",label:"Nama menu",value:p.name||"",full:true},{name:"category",label:"Kategori",type:"select",value:p.category||data.categories[0],options:data.categories.map(c=>({value:c,label:c}))},{name:"price",label:"Harga jual (Rp)",type:"number",min:0,value:p.price??0},{name:"hpp",label:"HPP internal (Rp)",type:"number",min:0,value:p.hpp??0},{name:"image",label:"Gambar menu (opsional)",type:"file",required:false,full:true},{name:"removeImage",label:"Hapus gambar tersimpan? ketik YA jika ingin menghapus",required:false,full:true,value:""}]}
function editProduct(id){if(!roleCan("menu"))return toast("Hak akses tidak mengizinkan perubahan menu.");const p=product(id);if(!p)return;openForm("Edit menu",productFields(p),o=>{Object.assign(p,{name:o.name.trim(),category:o.category,icon:o.icon||"🍴",price:Number(o.price),hpp:Number(o.hpp),stock:Number(p.stock)||0});if(o.image)p.image=o.image;if(o.removeImage?.trim().toUpperCase()==="YA")delete p.image;persist();renderAll();toast("Menu diperbarui")},p)}
function addProduct(){if(!roleCan("menu"))return toast("Hak akses tidak mengizinkan perubahan menu.");if(!data.categories.length)return toast("Buat kategori terlebih dahulu.");openForm("Tambah menu",productFields(),o=>{data.products.push({id:Date.now(),name:o.name.trim(),category:o.category,icon:o.icon||"🍴",price:Number(o.price),hpp:Number(o.hpp),stock:0,image:o.image||"",active:true,createdAt:new Date().toISOString()});persist();renderAll();toast("Menu baru ditambahkan")})}
function addPromo(id){if(!roleCan("discount"))return toast("Hak akses tidak mengizinkan pemberian diskon.");const p=id?data.promos.find(x=>x.id===Number(id)):null;const fields=[{name:"name",label:"Nama promo",value:p?.name||"Diskon menu",full:true},{name:"productId",label:"Menu yang didiskon",type:"select",value:p?.productId||activeProducts()[0]?.id,options:activeProducts().map(x=>({value:x.id,label:x.name}))},{name:"type",label:"Jenis diskon",type:"select",value:p?.type||"percent",options:[{value:"percent",label:"Persentase (%)"},{value:"nominal",label:"Nominal (Rp)"}]},{name:"amount",label:"Nilai diskon",type:"number",min:1,value:p?.amount||10},{name:"start",label:"Tanggal mulai",type:"date",value:p?.start||today()},{name:"end",label:"Tanggal berakhir",type:"date",value:p?.end||today()}];openForm(p?"Edit promo":"Buat promo",fields,o=>{if(o.end<o.start)return toast("Tanggal akhir harus sama atau setelah tanggal mulai.");const obj={id:p?.id||Date.now(),name:o.name,productId:Number(o.productId),type:o.type,amount:Number(o.amount),start:o.start,end:o.end,active:p?.active??true};if(p)Object.assign(p,obj);else data.promos.push(obj);persist();renderPromos();renderPosProducts();renderCart();toast("Promo disimpan")},p||{})}
function addFinance(){if(!["owner","admin"].includes(userRole()))return toast("Akses keuangan hanya untuk owner.");openForm("Catat keuangan",[{name:"type",label:"Jenis",type:"select",options:[{value:"Pengeluaran",label:"Pengeluaran"},{value:"Pemasukan",label:"Pemasukan"}]},{name:"category",label:"Kategori",value:"Operasional"},{name:"amount",label:"Nominal (Rp)",type:"number",min:1},{name:"date",label:"Tanggal",type:"date",value:today()},{name:"note",label:"Catatan",full:true}],o=>{data.finance.unshift({id:Date.now(),...o,amount:Number(o.amount)});persist();renderFinance();toast("Catatan keuangan disimpan")})}
function adjustStock(id){const p=product(id);if(!p)return;openForm("Penyesuaian stok",[{name:"name",label:"Menu",value:p.name,required:false,full:true},{name:"mode",label:"Jenis penyesuaian",type:"select",options:[{value:"set",label:"Atur jumlah stok"},{value:"add",label:"Tambah stok"},{value:"remove",label:"Kurangi stok"}]},{name:"qty",label:"Jumlah",type:"number",min:0,value:p.stock},{name:"note",label:"Catatan",full:true,required:false}],o=>{const q=Number(o.qty);p.stock=o.mode==="set"?q:o.mode==="add"?p.stock+q:Math.max(0,p.stock-q);persist();renderAll();toast("Stok diperbarui")},{name:p.name,qty:p.stock})}
function openDetail(s){$("#detail-content").innerHTML=`<div class="modal-head"><div><p class="eyebrow">DETAIL TRANSAKSI</p><h2>${esc(s.id)}</h2></div></div><div class="simple-list">${s.items.map(i=>`<div class="simple-row"><span>${esc(i.name)} × ${i.qty}<small>Harga jual: ${money(i.paidPrice)} / item</small></span><b>${money(i.paidPrice*i.qty)}</b></div>`).join("")}<div class="simple-row"><span>Subtotal</span><b>${money(s.subtotal)}</b></div><div class="simple-row"><span>Diskon</span><b>-${money(s.discount)}</b></div>${s.delivery&&s.deliveryFee?`<div class="simple-row"><span>Ongkir delivery</span><b>${money(s.deliveryFee)}</b></div>`:""}<div class="simple-row"><strong>Total</strong><strong>${money(s.total)}</strong></div><div class="simple-row"><span>Pembayaran / kasir</span><b>${esc(s.payment)} / ${esc(s.cashier)}</b></div></div><div class="modal-actions"><button class="btn primary" id="detail-reprint">Cetak struk</button></div>`;$("#detail-reprint").onclick=()=>showReceipt(s);$("#detail-dialog").showModal()}
function exportCSV(rows,filename){if(!rows.length)return toast("Tidak ada data untuk diekspor.");const cols=[...new Set(rows.flatMap(Object.keys))];const csv=[cols.join(","),...rows.map(r=>cols.map(c=>`"${String(r[c]??"").replace(/"/g,'""')}"`).join(","))].join("\r\n");const a=document.createElement("a");a.href=URL.createObjectURL(new Blob(["\ufeff"+csv],{type:"text/csv;charset=utf-8"}));a.download=filename;a.click();URL.revokeObjectURL(a.href)}
function backup(){const blob=new Blob([JSON.stringify(data,null,2)],{type:"application/json"}),a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download="orion-backup-"+today()+".json";a.click();URL.revokeObjectURL(a.href)}
async function initBackend(){if(localMode()){try{if(localStorage.getItem("orion_local_session_v1")==="active"){activeUser={name:"Admin Outlet",email:"admin@orion.local",role:"owner"};showApp();}}catch(e){console.warn("Sesi lokal tidak dapat dipulihkan",e)}return;}try{if(!window.supabase?.createClient)throw new Error("SDK tidak termuat");supabase=window.supabase.createClient(window.ORION_SUPABASE_URL,window.ORION_SUPABASE_ANON_KEY,{auth:{flowType:"pkce",detectSessionInUrl:true,autoRefreshToken:true,persistSession:true}});$("#login-message").textContent="Supabase terhubung. Masuk menggunakan email atau nomor HP dan password.";$("#sync-help").textContent="Supabase terkonfigurasi. Pastikan schema.sql sudah dijalankan dan URL aplikasi sudah diizinkan di Authentication → URL Configuration.";$("#backend-status").textContent="Supabase terkonfigurasi";const params=new URLSearchParams(location.hash.slice(1));const query=new URLSearchParams(location.search);const isSignupCallback=params.get("type")==="signup"||query.get("type")==="signup";const authError=params.get("error_description")||query.get("error_description");if(authError){setAuthMessage("Verifikasi email belum berhasil: "+authError.replace(/\+/g," "),true);history.replaceState(null,"",location.pathname+location.search)}const {data:{session}}=await supabase.auth.getSession();if(session){await activateSession(session.user);await pullRemote();showApp();if(isSignupCallback){toast("Email terverifikasi. Akun berhasil dibuat dan login.");history.replaceState(null,"",location.pathname+location.search)}}else if(isSignupCallback&&!authError){setAuthMessage("Tautan email sudah dibuka, tetapi sesi login belum terbentuk. Coba masuk dengan email dan password; pastikan template email dan URL redirect Supabase sudah benar.",true);history.replaceState(null,"",location.pathname+location.search)}supabase.auth.onAuthStateChange(async(event,sessionNow)=>{if((event==="SIGNED_IN"||event==="INITIAL_SESSION")&&sessionNow&&!activeUser){try{await activateSession(sessionNow.user);await pullRemote();showApp();if(isSignupCallback){toast("Email terverifikasi. Akun berhasil dibuat dan login.");history.replaceState(null,"",location.pathname+location.search)}}catch(err){console.error(err);setAuthMessage("Login berhasil tetapi profil/data belum siap: "+err.message,true)}}});supabase.channel("orion-pos-live").on("postgres_changes",{event:"*",schema:"public",table:"pos_state"},async()=>{await pullRemote();renderAll()}).subscribe();}catch(e){console.error(e);setAuthMessage("Koneksi Supabase gagal: "+e.message,true)}}
async function activateSession(user){activeUser={name:user.user_metadata?.display_name||user.email?.split("@")[0]||user.phone||"Pengguna",email:user.email||"",phone:user.phone||"",authId:user.id,role:"employee"};const pr=await supabase.from("pos_profiles").select("display_name,role,active").eq("id",user.id).maybeSingle();if(pr.error)throw pr.error;if(pr.data){if(pr.data.active===false)throw new Error("Akun dinonaktifkan");activeUser.name=pr.data.display_name||activeUser.name;activeUser.role=pr.data.role||"employee"}}
async function pullRemote(){if(!supabase)return;const {data:rows,error}=await supabase.from("pos_state").select("payload").eq("id",1).maybeSingle();if(error)throw error;if(rows?.payload){window.__orionPullingRemote=true;data={...ORION_DB.fresh(),...rows.payload};ORION_DB.save(data);window.__orionPullingRemote=false}}
async function pushRemote(){if(!supabase)return;const {error}=await supabase.from("pos_state").upsert({id:1,payload:data,updated_at:new Date().toISOString()});if(error)throw error}
function showApp(){if(!activeUser)activeUser={name:"Admin Outlet",email:"admin@orion.local",role:"owner"};if(!activeUser.role)activeUser.role="employee";$("#login-screen").classList.add("hidden");$("#app").classList.remove("hidden");applyRoleUI();renderAll();if(!canOpenPage("kasir"))showPage("kasir")}
let signupMode=false;
function setAuthMessage(message,isError=false){const el=$("#login-message");el.textContent=message;el.classList.toggle("error",!!isError);el.classList.toggle("verification",!isError&&/verifikasi email|buka gmail|konfirmasi email|langkah berikutnya/i.test(message))}
function toggleSignupMode(){signupMode=!signupMode;$("#signup-name-wrap").classList.toggle("hidden",!signupMode);$("#signup-name").required=signupMode;$("#login-submit").textContent=signupMode?"Daftar akun":"Masuk";$("#signup-toggle").textContent=signupMode?"Kembali ke login":"Buat akun baru";$(".login-card h1").textContent=signupMode?"Daftar akun POS":"Masuk ke POS";$("#login-password").autocomplete=signupMode?"new-password":"current-password";setAuthMessage(signupMode?"PENTING: akun belum aktif sebelum verifikasi. Setelah daftar, buka Gmail dan verifikasi alamat email melalui tautan yang kami kirim. Setelah tautan diklik, kamu akan diarahkan kembali ke aplikasi. Jika email tidak masuk, periksa Spam/Promosi; pengiriman email harus aktif di pengaturan Supabase. Untuk nomor HP, verifikasi memakai SMS jika Phone Auth diaktifkan.":(localMode()?"Mode lokal demo: admin@orion.local / orion123.":"Masuk menggunakan email atau nomor HP dan password."))}
function isPhoneIdentifier(value){return !String(value).includes("@")} 
async function login(e){e.preventDefault();const identifier=$("#login-email").value.trim(),password=$("#login-password").value;if(signupMode){if(!supabase){setAuthMessage("Pendaftaran online belum aktif. Periksa URL dan publishable key di js/supabase-config.js.",true);return}const displayName=$("#signup-name").value.trim();if(!displayName){setAuthMessage("Nama lengkap wajib diisi.",true);return}if(password.length<6){setAuthMessage("Password minimal 6 karakter.",true);return}const isPhone=isPhoneIdentifier(identifier);if(isPhone&&!/^\+[1-9]\d{7,14}$/.test(identifier)){setAuthMessage("Nomor HP harus format internasional, contoh +6281234567890.",true);return}const options={data:{display_name:displayName},emailRedirectTo:location.origin+location.pathname};const payload=isPhone?{phone:identifier,password,options}:{email:identifier,password,options};const {data:res,error}=await supabase.auth.signUp(payload);if(error){setAuthMessage(error.message,true);return}if(!res.session){setAuthMessage(isPhone?"Pendaftaran nomor HP diproses. Periksa SMS untuk kode verifikasi jika Phone Auth dan penyedia SMS sudah aktif.":"PENDAFTARAN BELUM AKTIF. Akun belum dapat digunakan sampai verifikasi selesai. Buka Gmail untuk alamat "+identifier+", lalu klik tautan konfirmasi yang dikirim Supabase. Setelah dikonfirmasi, tautan akan mengarahkan kembali ke aplikasi dan login otomatis jika konfigurasi redirect benar. Profil POS baru dibuat setelah Supabase menandai akun terverifikasi. Jika email belum masuk, periksa Spam/Promosi dan pengaturan email Supabase.");return}await activateSession(res.user);await pullRemote();showApp();toast("Akun berhasil dibuat");return}
if(supabase){const payload=isPhoneIdentifier(identifier)?{phone:identifier,password}:{email:identifier,password};const {data:res,error}=await supabase.auth.signInWithPassword(payload);if(error){setAuthMessage(error.message,true);return}try{await activateSession(res.user);await pullRemote()}catch(err){setAuthMessage("Gagal membaca profil/data online: "+err.message,true);return}showApp();return}if(identifier==="admin@orion.local"&&password==="orion123"){activeUser={name:"Admin Outlet",email:identifier,role:"owner"};try{localStorage.setItem("orion_local_session_v1","active")}catch(e){}showApp();toast("Login demo berhasil. Sesi tersimpan di perangkat ini.")}else{setAuthMessage("Akun demo: admin@orion.local / orion123. Akun demo hanya untuk mode lokal.",true)}}
async function createStaffAccount(e){e.preventDefault();if(!["owner","admin"].includes(userRole()))return toast("Hanya owner yang dapat membuat akun staf.");if(!supabase)return toast("Supabase belum terhubung.");const name=$("#staff-name").value.trim(),identifier=$("#staff-identifier").value.trim(),password=$("#staff-password").value,role=$("#staff-role").value,msg=$("#staff-account-message");if(password.length<6){msg.textContent="Password minimal 6 karakter.";return}const phone=isPhoneIdentifier(identifier);if(phone&&!/^\+[1-9]\d{7,14}$/.test(identifier)){msg.textContent="Nomor HP harus format +628...";return}const secondary=window.supabase.createClient(window.ORION_SUPABASE_URL,window.ORION_SUPABASE_ANON_KEY,{auth:{persistSession:false,autoRefreshToken:false,detectSessionInUrl:false}});const options={data:{display_name:name},emailRedirectTo:location.origin+location.pathname};const {data:created,error}=await secondary.auth.signUp(phone?{phone:identifier,password,options}:{email:identifier,password,options});if(error){msg.textContent=error.message;msg.classList.add("error");return}if(!created.user){msg.textContent="Supabase tidak mengembalikan akun baru.";return}if(role==="manager"){const {error:roleError}=await supabase.rpc("pos_owner_set_role",{target_user_id:created.user.id,new_role:"manager"});if(roleError){msg.textContent="Akun dibuat sebagai karyawan, tetapi penetapan manager gagal. Jalankan fungsi SQL v2.27 lalu coba ubah peran: "+roleError.message;msg.classList.add("error");return}}msg.classList.remove("error");msg.textContent="Akun "+name+" berhasil dibuat sebagai "+(role==="manager"?"manager":"karyawan")+". Jika konfirmasi aktif, pengguna harus mengonfirmasi email/SMS sebelum login.";$("#staff-account-form").reset();await secondary.auth.signOut().catch(()=>{});}
async function logout(){if(supabase)await supabase.auth.signOut();try{localStorage.removeItem("orion_local_session_v1")}catch(e){}activeUser=null;$("#app").classList.add("hidden");$("#login-screen").classList.remove("hidden");$("#login-password").value=""}
function closeOutlet(){const list=transactionsForDay(),sales=list.reduce((a,s)=>a+s.total,0),hpp=list.reduce((a,s)=>a+s.hpp,0);$("#close-summary").innerHTML=`<div class="metrics"><article class="metric"><span>Transaksi</span><strong>${list.length}</strong></article><article class="metric"><span>Omzet</span><strong>${money(sales)}</strong></article><article class="metric"><span>Laba kotor</span><strong>${money(sales-hpp)}</strong></article></div>`;if(data.outletClosed){data.outletClosed=false;persist();renderStatus();toast("Outlet dibuka kembali");return}$("#close-dialog").showModal()}
