 const reset=$("#cashier-theme-reset");if(reset)reset.onclick=()=>{Object.keys(POS_THEME_DEFAULTS).forEach(k=>{if(form.elements[k])form.elements[k].value=POS_THEME_DEFAULTS[k]})};
